250	    document.querySelectorAll('[data-reveal]').forEach(el => el.classList.add('reveal'));
251	    var revealObserver = new IntersectionObserver(function(entries) {
252	      entries.forEach(function(e) { if (e.isIntersecting) { e.target.classList.add('visible'); revealObserver.unobserve(e.target); } });
