257	    function animateCounters() {
258	      document.querySelectorAll('[data-count]').forEach(function(el) {
259	        if (el.dataset.counted) return;
260	        el.dataset.counted = '1';
261	        var target = parseFloat(el.dataset.count), prefix = el.dataset.prefix || '', suffix = el.dataset.suffix || '';
262	        var start = performance.now(), duration = 1200;
263	        (function tick(now) {
264	          var p = Math.min((now - start) / duration, 1), eased = 1 - Math.pow(1 - p, 3);
265	          el.textContent = prefix + Math.round(target * eased).toLocaleString() + suffix;
266	          if (p < 1) requestAnimationFrame(tick);
