<html lang="en" class="theme-dark">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=1680, height=2380">
  <title>Neural Circuit Mapping - Nature 2024</title>
  <link href="/app/libs/fonts/inter.css" rel="stylesheet">
  <script src="/app/libs/html-to-image.js"></script>
  <style>
    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

    html.theme-dark {
      --bg: #0a0f1a;
      --surface: #111827;
      --surface-hover: #1e293b;
      --border: rgba(59, 130, 246, 0.15);
      --text: #f1f5f9;
      --text-secondary: #94a3b8;
      --accent: #3b82f6;
      --accent-secondary: #06b6d4;
      --accent-warm: #f59e0b;
      --positive: #10b981;
    }

    body {
      width: 1680px;
      height: 2380px;
      overflow: hidden;
      font-family: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
      background: var(--bg);
      color: var(--text);
      display: flex;
      flex-direction: column;
      line-height: 1.5;
    }

    h1, h2, h3, h4 { letter-spacing: -0.03em; line-height: 1.15; }
    h1 { font-weight: 700; }
    h2 { font-weight: 600; }
    h3 { font-weight: 600; }

    /* Header */
    .poster-header {
      padding: 32px 48px 24px;
      background: linear-gradient(180deg, #0f172a 0%, var(--bg) 100%);
      border-bottom: 1px solid var(--border);
    }
    .journal-badge {
      display: inline-block;
      background: linear-gradient(135deg, var(--accent) 0%, #1d4ed8 100%);
      color: white;
      font-size: 13px;
      font-weight: 600;
      padding: 6px 14px;
      border-radius: 4px;
      margin-bottom: 16px;
      letter-spacing: 0.02em;
    }
    .poster-title {
      font-size: 52px;
      margin-bottom: 12px;
      background: linear-gradient(135deg, #f1f5f9 0%, #cbd5e1 100%);
      -webkit-background-clip: text;
      -webkit-text-fill-color: transparent;
      background-clip: text;
    }
    .poster-subtitle {
      font-size: 22px;
      color: var(--text-secondary);
      max-width: 900px;
    }
    .doi-text {
      margin-top: 12px;
      font-size: 14px;
      color: var(--text-secondary);
      font-family: monospace;
    }

    /* Metrics Banner */
    .metrics-banner {
      display: flex;
      justify-content: space-between;
      padding: 28px 48px;
      background: linear-gradient(90deg, #0f172a 0%, #1e293b 50%, #0f172a 100%);
      border-bottom: 1px solid var(--border);
    }
    .metric-item {
      text-align: center;
      flex: 1;
    }
    .metric-item:not(:last-child) {
      border-right: 1px solid var(--border);
    }
    .metric-value {
      font-size: 48px;
      font-weight: 700;
      background: linear-gradient(135deg, var(--accent) 0%, var(--accent-secondary) 100%);
      -webkit-background-clip: text;
      -webkit-text-fill-color: transparent;
      background-clip: text;
      line-height: 1;
      margin-bottom: 6px;
    }
    .metric-value.accent-warm {
      background: linear-gradient(135deg, var(--accent-warm) 0%, #fbbf24 100%);
      -webkit-background-clip: text;
      -webkit-text-fill-color: transparent;
      background-clip: text;
    }
    .metric-label {
      font-size: 14px;
      font-weight: 600;
      color: var(--text);
      text-transform: uppercase;
      letter-spacing: 0.08em;
      margin-bottom: 4px;
    }
    .metric-context {
      font-size: 12px;
      color: var(--text-secondary);
    }

    /* Main Content */
    .poster-content {
      flex: 1;
      display: grid;
      grid-template-columns: 1fr 1.4fr;
      grid-template-rows: auto auto;
      gap: 0;
      padding: 0;
    }

    .content-section {
      padding: 32px 40px;
      border-bottom: 1px solid var(--border);
    }
    .content-section.full-width {
      grid-column: 1 / -1;
    }

    .section-title {
      font-size: 20px;
      color: var(--accent);
      text-transform: uppercase;
      letter-spacing: 0.1em;
      margin-bottom: 20px;
      display: flex;
      align-items: center;
      gap: 12px;
    }
    .section-title::before {
      content: '';
      display: block;
      width: 4px;
      height: 24px;
      background: linear-gradient(180deg, var(--accent) 0%, var(--accent-secondary) 100%);
      border-radius: 2px;
    }

    /* Left Column - Background & Methods */
    .left-column {
      border-right: 1px solid var(--border);
    }

    /* Background */
    .background-text {
      font-size: 17px;
      line-height: 1.7;
      color: var(--text);
    }
    .background-text p {
      margin-bottom: 16px;
    }

    /* Methods */
    .methods-grid {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 16px;
    }
    .method-card {
      background: var(--surface);
      border: 1px solid var(--border);
      border-radius: 8px;
      padding: 18px;
    }
    .method-card-title {
      font-size: 14px;
      font-weight: 600;
      color: var(--accent-secondary);
      margin-bottom: 8px;
      text-transform: uppercase;
      letter-spacing: 0.05em;
    }
    .method-card-desc {
      font-size: 14px;
      color: var(--text-secondary);
      line-height: 1.5;
    }

    .pipeline-visual {
      display: flex;
      align-items: center;
      justify-content: space-between;
      padding: 20px 0;
      margin-top: 16px;
    }
    .pipeline-step {
      display: flex;
      flex-direction: column;
      align-items: center;
      text-align: center;
      flex: 1;
    }
    .pipeline-icon {
      width: 56px;
      height: 56px;
      background: linear-gradient(135deg, var(--accent) 0%, var(--accent-secondary) 100%);
      border-radius: 12px;
      display: flex;
      align-items: center;
      justify-content: center;
      margin-bottom: 10px;
    }
    .pipeline-icon svg {
      width: 28px;
      height: 28px;
      stroke: white;
      fill: none;
      stroke-width: 2;
    }
    .pipeline-label {
      font-size: 13px;
      font-weight: 600;
      color: var(--text);
      margin-bottom: 4px;
    }
    .pipeline-desc {
      font-size: 11px;
      color: var(--text-secondary);
    }
    .pipeline-arrow {
      color: var(--accent);
      font-size: 24px;
      margin: 0 8px;
    }

    /* Key Findings - Full Width */
    .findings-section {
      background: linear-gradient(180deg, var(--surface) 0%, var(--bg) 100%);
    }
    .findings-grid {
      display: grid;
      grid-template-columns: repeat(2, 1fr);
      gap: 20px;
    }
    .finding-card {
      background: var(--surface);
      border: 1px solid var(--border);
      border-radius: 10px;
      padding: 24px;
      position: relative;
      overflow: hidden;
    }
    .finding-card::before {
      content: '';
      position: absolute;
      top: 0;
      left: 0;
      width: 4px;
      height: 100%;
      background: linear-gradient(180deg, var(--accent) 0%, var(--accent-secondary) 100%);
    }
    .finding-card.accent-warm::before {
      background: linear-gradient(180deg, var(--accent-warm) 0%, #fbbf24 100%);
    }
    .finding-card.accent-positive::before {
      background: linear-gradient(180deg, var(--positive) 0%, #34d399 100%);
    }
    .finding-stat {
      font-size: 36px;
      font-weight: 700;
      color: var(--accent);
      margin-bottom: 8px;
    }
    .finding-stat.accent-warm { color: var(--accent-warm); }
    .finding-stat.accent-positive { color: var(--positive); }
    .finding-title {
      font-size: 16px;
      font-weight: 600;
      color: var(--text);
      margin-bottom: 8px;
    }
    .finding-desc {
      font-size: 14px;
      color: var(--text-secondary);
      line-height: 1.5;
    }

    /* Motifs Visual */
    .motifs-visual {
      display: flex;
      align-items: center;
      gap: 24px;
      margin-top: 20px;
      padding: 20px;
      background: var(--surface);
      border-radius: 10px;
      border: 1px solid var(--border);
    }
    .motif-diagram {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 12px;
      flex: 1;
    }
    .motif-node {
      aspect-ratio: 1;
      background: var(--surface-hover);
      border: 2px solid var(--border);
      border-radius: 8px;
      display: flex;
      align-items: center;
      justify-content: center;
      position: relative;
    }
    .motif-node svg {
      width: 36px;
      height: 36px;
      stroke: var(--accent);
      fill: none;
      stroke-width: 2;
    }
    .motif-label {
      position: absolute;
      bottom: -20px;
      font-size: 10px;
      color: var(--text-secondary);
